    {"week": 23, "title": "Competitive Moat — Wide Moat Stocks", "title_en": "Competitive Moat — Finding Wide Moat Stocks", "category": "Fundamental Analysis", "level": "Advanced", "description": "Warren Buffett's moat concept for India", "slides": [{"heading": "Moat Kya Hota Hai", "points": ["Moat ek business ka sustainable competitive advantage hai", "Warren Buffett ne yeh term famous banaya value investing mein", "Strong moat wali company competitors se apni market share protect kar paati hai", "Moat wali companies aksar consistent high margins maintain karti hain"]}, {"heading": "5 Types of Moats", "points": ["Brand power — customers premium pay karte hain trust ki wajah se", "Network effect — jitne zyada users, utna zyada valuable product", "Cost advantage — competitors se kam cost mein produce karna", "Switching cost — customer ke liye brand change karna mushkil/costly hona", "Regulatory/license advantage — limited players ko hi entry milti hai"]}, {"heading": "India Mein Wide Moat Stocks", "points": ["Asian Paints — strong distribution network aur brand loyalty", "HDFC Bank — trust aur scale ka combination", "Titan — jewellery mein brand aur retail network dono strong", "Yeh sirf examples hain, apna analysis karke hi invest karo"]}, {"heading": "Moat Kitne Saalo Tak", "points": ["Kuch moats decades tak sustain hote hain (jaise strong brands)", "Technology disruption se purane moats bhi kamzor ho sakte hain", "Moat ki durability regularly re-assess karna zaroori hai", "Ek moat permanent nahi hota — competitive landscape change hoti rehti hai"]}, {"heading": "Moat Wala Stock Kab Khareedein", "points": ["Quality business ko fair valuation par khareedna best strategy hai", "Bahut zyada premium valuation par bhi wait karna sahi ho sakta hai", "Market correction ke time quality stocks discount par mil sakte hain", "Moat + reasonable price combination long-term wealth banata hai"]}]},
    {"week": 24, "title": "Valuation — Fair Value Kaise Calculate Karein", "title_en": "Valuation — How to Calculate Fair Value", "category": "Fundamental Analysis", "level": "Advanced", "description": "DCF, Graham number, earnings-based", "slides": [{"heading": "Valuation Kyon Zaroori Hai", "points": ["Achhi company bhi galat price par khareedne se poor return de sakti hai", "Valuation batata hai stock uski real worth ke against sasta hai ya mahanga", "Overpaying se future returns compress ho jaate hain", "Valuation discipline long-term investing ka core skill hai"]}, {"heading": "P/E Based Valuation", "points": ["Company ke P/E ko uske historical average aur peers se compare karo", "Growth-adjusted valuation (PEG) zyada complete picture deta hai", "Sirf ek metric par depend karna risky strategy hai", "P/E ek starting point hai, poora valuation analysis nahi"]}, {"heading": "Graham Number", "points": ["Formula: sqrt(22.5 x EPS x Book Value per Share)", "Benjamin Graham (Warren Buffett ke teacher) ne yeh method banaya", "Conservative fair value estimate deta hai value investors ke liye", "Growth companies ke liye yeh method kam suitable hota hai"]}, {"heading": "DCF Simplified", "points": ["DCF (Discounted Cash Flow) future cash flows ko aaj ki value mein convert karta hai", "Assumption-heavy method hai — growth rate aur discount rate critical hote hain", "Zyada complex businesses ke liye simplify karna mushkil ho sakta hai", "Professional investors isse detailed valuation ke liye use karte hain"]}, {"heading": "Margin of Safety", "points": ["Estimated fair value se kaafi kam price par khareedna margin of safety hai", "Yeh galat estimates aur unexpected events se protection deta hai", "Warren Buffett ki investing philosophy ka core concept hai", "Jitna bada margin of safety, utna kam downside risk"]}]},
    {"week": 25, "title": "Swing Trading — 5-10% Kaise Kamayein", "title_en": "Swing Trading — Making 5-10% in a Week", "category": "Trading Strategies", "level": "Intermediate", "description": "Complete swing trading system", "slides": [{"heading": "Swing vs Intraday vs Positional", "points": ["Intraday: same din entry aur exit, overnight risk nahi", "Swing: kuch din se 1-2 hafte tak hold karna, short-term moves capture karna", "Positional: 1-3 mahine tak hold karna, bigger trends capture karna", "Har style ka apna risk-reward aur time commitment hota hai"]}, {"heading": "Best Timeframe for Swing", "points": ["Daily chart swing trading ke liye sabse common timeframe hai", "Weekly chart bigger trend confirm karne mein madad karta hai", "4-hour chart precise entry timing ke liye use hota hai", "Multiple timeframe analysis better decision-making deta hai"]}, {"heading": "Entry Criteria", "points": ["Strong trend + support/resistance level + volume confirmation dekho", "Relative strength (stock market se behtar perform kar raha ho) check karo", "Clean chart pattern (breakout, base) ke saath entry lena better hai", "Kabhi bhi bina clear setup ke random entry mat lo"]}, {"heading": "Stop Loss Placement", "points": ["Stop loss recent swing low/high ke thoda neeche/upar rakho", "ATR (Average True Range) based SL volatility ke hisaab se adjust hota hai", "Bahut tight SL normal noise mein bhi stop out kar sakta hai", "SL hamesha entry se pehle hi decide karke rakhna chahiye"]}, {"heading": "Target Setting RR 1:2", "points": ["Risk-Reward ratio batata hai potential profit vs potential loss", "1:2 RR matlab Rs.1 risk karke Rs.2 kamane ka target", "Achhi RR ke saath even 40-50% win rate bhi profitable ho sakta hai", "Bina proper RR ke trade lena long term mein losing strategy hai"]}]},
    {"week": 26, "title": "Positional Trading — Hold 1-3 Mahine", "title_en": "Positional Trading — Hold for 1-3 Months", "category": "Trading Strategies", "level": "Intermediate", "description": "Positional trading with fundamentals + technicals", "slides": [{"heading": "Positional Trading Kya Hota Hai", "points": ["1-3 mahine tak stocks hold karna, bigger trend capture karne ke liye", "Technical aur fundamental dono factors combine kiye jaate hain", "Daily price noise ignore karke bigger picture par focus hota hai", "Kam frequency mein trade karna, patience zyada important hoti hai"]}, {"heading": "Stock Selection", "points": ["Strong fundamentals + technical breakout combination best hota hai", "Sector tailwind wale stocks ko priority dena chahiye", "Relative strength market se zyada honi chahiye", "Liquidity check karna zaroori hai easy entry-exit ke liye"]}, {"heading": "Entry Point Weekly Chart", "points": ["Weekly chart noise filter karke clean trend dikhata hai", "Weekly breakout daily breakout se zyada reliable maana jaata hai", "Weekly support/resistance levels bade moves ke liye important hote hain", "Entry weekly confirmation ke baad lena safer strategy hai"]}, {"heading": "Trailing Stop Loss", "points": ["Price favor mein move kare toh SL bhi upar/neeche shift karte jao", "Isse profit lock hota hai bina position exit kiye", "ATR ya moving average based trailing common methods hain", "Trend jab tak intact hai, position hold rakhne mein madad karta hai"]}, {"heading": "When to Exit Early", "points": ["Original thesis (jis wajah se enter kiya) galat sabit ho toh exit karo", "Major support break hona early exit ka signal hai", "Better opportunity milne par bhi capital rotate kiya ja sakta hai", "Ego se position hold karna (loss accept na karna) bada mistake hai"]}]},
    {"week": 27, "title": "Momentum Trading", "title_en": "Momentum Trading — Ride the Moving Stocks", "category": "Trading Strategies", "level": "Intermediate", "description": "Buy strength, sell weakness", "slides": [{"heading": "Momentum Kya Hai", "points": ["Momentum trading matlab already move kar rahe strong stocks ko follow karna", "'Buy high, sell higher' philosophy hai, 'buy low sell high' se different", "Strong stocks aksar strong hi rehte hain jab tak trend intact hai", "Momentum trading discipline aur quick decision-making maangta hai"]}, {"heading": "RS Relative Strength", "points": ["RS batata hai stock apne benchmark (Nifty) se behtar perform kar raha hai ya nahi", "High RS wale stocks market rally mein leaders hote hain", "RS ≥5 jaisi threshold genuine outperformance filter karti hai", "Weak RS wale stocks momentum strategy ke liye avoid karne chahiye"]}, {"heading": "VCP Pattern", "points": ["VCP (Volatility Contraction Pattern) — price range dheere dheere tight hota jaata hai", "Yeh accumulation aur upcoming breakout ka signal ho sakta hai", "Mark Minervini jaise traders ne yeh pattern popularize kiya", "Tight consolidation ke baad breakout aksar powerful hota hai"]}, {"heading": "Entry Timing with Volume", "points": ["Breakout ke exact time high volume ka hona confirmation deta hai", "Bina volume ke breakout fake ho sakta hai", "Entry breakout candle ke close ke baad lena safer hota hai", "Volume spike institutional participation dikhata hai"]}, {"heading": "Momentum Ka Life Cycle", "points": ["Har momentum move ka ek natural lifecycle hota hai — start, acceleration, exhaustion", "Exhaustion signs (weak volume, extended RSI) exit ka warning dete hain", "Bahut der se enter karna (trend ke end mein) risky hota hai", "Momentum trading mein timing entry se zyada exit important hoti hai"]}]},
    {"week": 28, "title": "Breakout Trading", "title_en": "Breakout Trading — Buying at New Highs", "category": "Trading Strategies", "level": "Intermediate", "description": "How to trade breakouts correctly", "slides": [{"heading": "Breakout Kya Hota Hai", "points": ["Price ek important resistance/consolidation level ko cross kare, yeh breakout hai", "Naye highs banane ki shuruaat aksar breakout se hoti hai", "Breakout genuine growth ya sirf noise, yeh confirm karna zaroori hai", "Achhe breakouts strong trends ki shuruaat ho sakte hain"]}, {"heading": "True vs False Breakout", "points": ["True breakout: high volume, close resistance ke upar, follow-through hota hai", "False breakout: low volume, jaldi wapas range mein aa jaata hai", "False breakouts (bull traps) beginners ko losses dete hain", "Confirmation ka wait karna false breakout se bachne ka best tareeka hai"]}, {"heading": "Volume Confirmation", "points": ["Breakout ke din volume normal average se kaafi zyada hona chahiye", "Low volume breakout ki reliability bahut kam hoti hai", "Volume institutional participation ka proof deta hai", "Volume ke bina sirf price breakout par trust karna risky hai"]}, {"heading": "Entry After Confirmation", "points": ["Breakout candle ke close hone ka wait karo, mid-candle entry avoid karo", "Retest entry (price wapas level par aakar bounce kare) safer option hai", "FOMO mein turant chase karna aksar bad entries deta hai", "Patience se confirmation lena long-term mein better results deta hai"]}, {"heading": "SL and Target", "points": ["Stop loss breakout level ke thoda neeche rakha jaata hai", "Target pattern ki height ya previous resistance levels se estimate hota hai", "RR ratio kam se kam 1:1.5-2 hona chahiye entry lene se pehle", "Trailing SL se bade moves mein extra profit capture ho sakta hai"]}]},
    {"week": 29, "title": "Base Entry — Sabse Kum Risk Ka Entry", "title_en": "Base Entry — The Lowest Risk Entry", "category": "Trading Strategies", "level": "Advanced", "description": "AI360 base entry before breakout", "slides": [{"heading": "Base Entry Kya Hai", "points": ["Base entry matlab breakout se pehle, consolidation zone mein hi enter karna", "Isse better average price aur bada potential upside milta hai", "Risk bhi zyada hota hai kyunki breakout confirm nahi hua hota", "Experienced traders is strategy ko zyada use karte hain"]}, {"heading": "Accumulation Zone", "points": ["Woh price range jahan smart money dheere dheere shares jama kar rahi ho", "Volume pattern se accumulation ka pata chal sakta hai", "Price tight range mein rehta hai is phase mein", "Accumulation ke baad aksar strong breakout follow hota hai"]}, {"heading": "VCP Pattern", "points": ["Volatility Contraction Pattern base entry identify karne ka key tool hai", "Har consecutive pullback pehle se chota hota jaata hai", "Yeh dikhata hai selling pressure dheere dheere kam ho raha hai", "Tightest point ke paas hi breakout ka anticipation hota hai"]}, {"heading": "Entry Timing", "points": ["Base ke tightest, low-volume part mein entry lena ideal hota hai", "Bahut jaldi enter karna extended consolidation ka risk rakhta hai", "Stop loss base ke low ke just neeche rakha jaata hai", "Patience zaroori hai — base develop hone mein hafte lag sakte hain"]}, {"heading": "Risk Reward from Base", "points": ["Base entry se stop loss tight rakha ja sakta hai (base ke low ke paas)", "Isse risk-reward ratio breakout entry se better ho sakta hai", "Lekin base fail hone (breakdown) ka risk bhi real hota hai", "Position sizing is risk ko manage karne ka key tareeka hai"]}]},
    {"week": 30, "title": "Trailing Stop Loss — Profit Ko Lock Karein", "title_en": "Trailing Stop Loss — Locking In Profits", "category": "Trading Strategies", "level": "Intermediate", "description": "TSL methods — fixed, ATR-based, AI360 bot", "slides": [{"heading": "Fixed SL vs Trailing SL", "points": ["Fixed SL entry ke time set hoti hai aur change nahi hoti", "Trailing SL price ke favor mein move karne ke saath upar/neeche shift hoti hai", "Trailing SL profits ko lock karti hai jabki upside khula rehta hai", "Fixed SL simple hai lekin bade moves ka fayda pura nahi utha paati"]}, {"heading": "ATR Based Trailing", "points": ["ATR (Average True Range) stock ki volatility measure karta hai", "SL ko ATR ke multiple (jaise 2x ATR) door rakha jaata hai", "Zyada volatile stock mein wider SL, kam volatile mein tighter SL", "Yeh method noise se bachate hue trend follow karne mein madad karta hai"]}, {"heading": "Breakeven Move", "points": ["Jab trade thoda profit mein chala jaaye, SL entry price par le aao", "Isse worst case mein bhi loss nahi hota, sirf breakeven hota hai", "Yeh psychological comfort deta hai position hold karne ke liye", "Bahut jaldi breakeven move karna bhi normal noise mein stop out kar sakta hai"]}, {"heading": "Progressive Locking", "points": ["Jaise jaise price favor mein move kare, profit ka hissa lock karte jao", "Har naye swing low/high par SL update karna ek common method hai", "Isse trend ke end tak position hold karna possible hota hai", "Discipline se follow karna is strategy ki success key hai"]}, {"heading": "AI360 Bot Ka TSL System", "points": ["Bot breakeven move, chandelier exit, aur progressive locking use karta hai", "TSL calculation paisa precision (integer paise) mein compare hoti hai", "Yeh same-value re-computation se duplicate alerts rokta hai", "Genuine price improvement hi naya TSL update trigger karta hai"]}]},
    {"week": 31, "title": "Intraday Trading — Sach Batata Hoon", "title_en": "Intraday Trading — The Honest Truth", "category": "Trading Strategies", "level": "Intermediate", "description": "Intraday reality check", "slides": [{"heading": "Intraday Trading Reality", "points": ["Zyada tar retail intraday traders consistently profit nahi kama paate", "High frequency trading costs (brokerage, taxes) returns kha jaate hain", "Discipline aur quick decision-making ki zaroorat hoti hai", "Yeh ek skill hai jo time aur practice maangti hai, guaranteed income nahi"]}, {"heading": "Kab Intraday Sahi Hai", "points": ["Jab aapke paas dedicated time ho market ke ghanton mein", "Jab aapne apna risk management system thoroughly test kiya ho", "Jab emotional discipline strong ho, losses ko accept kar sakte ho", "Beginners ke liye pehle paper trading se practice karna better hai"]}, {"heading": "Best Intraday Stocks India", "points": ["High liquidity wale large-cap stocks (Nifty 50 components) preferred hote hain", "Tight bid-ask spread wale stocks slippage kam karte hain", "News/results ke din high volatility wale stocks avoid karna beginners ke liye better hai", "F&O stocks zyada liquid hote hain intraday trading ke liye"]}, {"heading": "Gap and Go Strategy", "points": ["Stock overnight news ke saath gap up/down open karta hai", "Strong gap ke saath continuation ka pattern trade kiya jaata hai", "Gap fill ka risk bhi hota hai — pura gap wapas close ho sakta hai", "Volume confirmation gap continuation trades mein zaroori hai"]}, {"heading": "5 Non-Negotiable Rules", "points": ["Har trade se pehle stop loss decide karo, bina exception ke", "Overall capital ka 1-2% se zyada ek trade mein risk mat karo", "Revenge trading (loss ke baad turant bada trade) kabhi mat karo", "Trading plan follow karo, emotions ko decisions lene mat do", "Daily loss limit set karo aur usse hit hone par trading band karo"]}]},
    {"week": 32, "title": "Portfolio Building — Balanced Portfolio", "title_en": "Portfolio Building — Creating Balance", "category": "Trading Strategies", "level": "Intermediate", "description": "Complete portfolio construction", "slides": [{"heading": "Portfolio Kya Hota Hai", "points": ["Portfolio aapke sabhi investments (stocks, funds, etc.) ka combination hai", "Ek acchi portfolio risk ko diversify karke returns optimize karti hai", "Portfolio review karna regular financial discipline ka hissa hai", "Sirf ek stock/sector par depend karna high-risk approach hai"]}, {"heading": "Asset Allocation", "points": ["Equity, debt, gold jaise different asset classes mein paisa divide karna", "Age, risk appetite, aur goals ke hisaab se allocation decide hota hai", "Young investors zyada equity allocation afford kar sakte hain", "Allocation time ke saath adjust hona chahiye life stage ke hisaab se"]}, {"heading": "Diversification", "points": ["Alag sectors aur market caps mein invest karke risk spread karna", "Ek negative news se poora portfolio affect nahi hona chahiye", "Over-diversification (bahut zyada stocks) returns dilute kar sakta hai", "10-15 quality stocks generally achha balance maane jaate hain"]}, {"heading": "Rebalancing", "points": ["Time ke saath asset allocation apne target se drift kar jaata hai", "Rebalancing matlab wapas original allocation par laana", "Yearly ya half-yearly rebalancing common practice hai", "Yeh discipline profit booking aur risk control dono karta hai"]}, {"heading": "Quarterly Review", "points": ["Har quarter apni holdings ka performance review karna chahiye", "Company results, sector trends, aur original thesis check karo", "Underperforming ya thesis-broken stocks exit karne ka time ho sakta hai", "Review disciplined hona chahiye, emotional decisions se bachna chahiye"]}]},
    {"week": 33, "title": "Options Introduction — Call Put Basics", "title_en": "Options Introduction — Call and Put Basics", "category": "Options", "level": "Beginner", "description": "First introduction to options", "slides": [{"heading": "Option Contract Kya Hota Hai", "points": ["Option ek contract hai jo aapko right deta hai, obligation nahi", "Fixed price (strike) par future mein buy/sell karne ka right milta hai", "Har option ki ek expiry date hoti hai jiske baad woh worthless ho jaata hai", "Options stocks se kam capital mein leverage exposure dete hain"]}, {"heading": "Call Option", "points": ["Call option kharidne wale ko price upar jaane par profit hota hai", "Yeh right deta hai fixed price par stock BUY karne ka", "Agar price strike se upar na jaaye, sirf premium ka loss hota hai", "Bullish view rakhne wale traders call options buy karte hain"]}, {"heading": "Put Option", "points": ["Put option kharidne wale ko price neeche jaane par profit hota hai", "Yeh right deta hai fixed price par stock SELL karne ka", "Hedging ke liye bhi put options widely use hote hain", "Bearish view rakhne wale traders put options buy karte hain"]}, {"heading": "Premium Kya Hota Hai", "points": ["Premium woh price hai jo option buyer seller ko pay karta hai", "Yeh maximum amount hai jo option buyer risk mein daalta hai", "Premium intrinsic value aur time value dono se milkar banta hai", "Time ke saath premium ghatta hai (time decay/theta)"]}, {"heading": "Maximum Loss Limited", "points": ["Option buyer ka maximum loss sirf paid premium tak limited hota hai", "Yeh stock buying se different hai jahan loss theoretically unlimited ho sakta hai", "Yeh limited-risk feature options ko attractive banata hai beginners ke liye", "Lekin option seller ka risk unlimited bhi ho sakta hai — dhyaan rakhna zaroori hai"]}]},
    {"week": 34, "title": "Options Greeks — Delta Theta Vega", "title_en": "Options Greeks Simply Explained", "category": "Options", "level": "Intermediate", "description": "Greeks explained with Indian examples", "slides": [{"heading": "Greeks Kyon Zaroori Hain", "points": ["Greeks batate hain option price kin factors se affect hoti hai", "Bina Greeks samjhe options trading mein informed decisions lena mushkil hai", "Har Greek ek specific risk/sensitivity measure karta hai", "Professional option traders Greeks ko daily monitor karte hain"]}, {"heading": "Delta", "points": ["Delta batata hai stock price Re.1 move kare toh option price kitna badlega", "Call options ka delta 0 se 1 ke beech, put options ka -1 se 0 ke beech hota hai", "ATM options ka delta approximately 0.5 hota hai", "High delta options stock ke saath zyada closely move karte hain"]}, {"heading": "Theta", "points": ["Theta time decay measure karta hai — har din option value kam hoti hai", "Expiry jitni close aati hai, theta decay utni fast hoti hai", "Option buyers ke liye theta enemy hai, sellers ke liye friend", "Weekends/holidays mein bhi theta decay chalta rehta hai"]}, {"heading": "Vega", "points": ["Vega batata hai implied volatility change se option price kaise affect hoti hai", "High volatility mein options mehnge, low volatility mein saste hote hain", "Events (results, budget) se pehle vega/volatility badh jaati hai", "Vega samajhna especially option sellers ke liye important hai"]}, {"heading": "Practice Karein", "points": ["Paper trading se pehle Greeks ko practically observe karo", "Options chain mein live Greeks values dekh sakte ho broker apps mein", "Chhote position se real trading shuru karo Greeks samajhne ke baad", "Theory ke saath practical observation combine karna best learning hai"]}]},
    {"week": 35, "title": "Option Buying Strategy — CE PE Kab Khareedein", "title_en": "Option Buying — When to Buy CE and PE", "category": "Options", "level": "Intermediate", "description": "Directional option buying", "slides": [{"heading": "3 Cheezein Sahi Karni Hain", "points": ["Direction sahi predict karna (market kis taraf jayega)", "Timing sahi rakhna (kab tak move hoga)", "Sahi strike aur expiry select karna", "Teeno mein se ek bhi galat hone par loss ho sakta hai"]}, {"heading": "Strike Selection ATM OTM ITM", "points": ["ATM (At The Money) — strike current price ke bahut paas hai", "OTM (Out of The Money) — saste hote hain but lower probability", "ITM (In The Money) — mehnge hote hain but higher probability", "Beginners ke liye ATM/slightly ITM options better balance dete hain"]}, {"heading": "Expiry Selection", "points": ["Current month/week expiry mein liquidity sabse zyada hoti hai", "Far expiry options mein spread wide aur volume kam hota hai", "AI360 system current expiry (max 5 din rollover tak next month) use karta hai", "Options ko intraday/1-2 din ke hold ke liye treat karna chahiye"]}, {"heading": "VIX Check", "points": ["High VIX ke time options premium mehnge hote hain", "Low VIX (15-18 zone) buying ke liye better environment maana jaata hai", "VIX check kiye bina option buy karna ek common beginner mistake hai", "VIX events (results, elections) ke around spike kar sakta hai"]}, {"heading": "Stop Loss and Exit", "points": ["Options mein SL percentage-based (jaise 20% premium loss) rakha jaata hai", "Time-based exit bhi zaroori hai — options intraday/1-2 din hold ke liye hain", "Stock-anchored exit strategy bhi use ki ja sakti hai", "Bina SL discipline ke option buying gambling ban sakti hai"]}]},
    {"week": 36, "title": "Option Selling — Consistent Income", "title_en": "Option Selling — Generating Consistent Income", "category": "Options", "level": "Advanced", "description": "Covered call, cash secured put, spreads", "slides": [{"heading": "Option Sellers Kyun Jeette Hain", "points": ["Approximately 80% options expire worthless — yeh statistics option sellers ke favor mein hai", "Time decay (theta) sellers ke liye continuously kaam karta hai", "Sellers ko sirf direction sahi nahi, range mein rehna kaafi hota hai", "Yeh ek insurance company jaisa business model hai — consistent premium income"]}, {"heading": "Covered Call", "points": ["Already owned stock ke against call option sell karna", "Extra income generate hota hai stock holding ke saath", "Agar stock bahut upar chala jaaye toh upside limited ho jaata hai", "Sideways ya mild-bullish market mein yeh strategy achhi kaam karti hai"]}, {"heading": "Cash Secured Put", "points": ["Put option sell karna, saath mein poora cash reserve rakhna assignment ke liye", "Agar stock assign ho jaaye, aapko discount price par stock milta hai", "Agar assign na ho, premium income mil jaati hai", "Yeh strategy un stocks ke liye achhi hai jinhe aap anyway khareedna chahte ho"]}, {"heading": "Bull Put Spread", "points": ["Ek put sell karo aur ek lower strike put buy karo (hedge ke liye)", "Maximum loss limited hoti hai (unlike naked put selling)", "Premium income kam hoti hai lekin risk bhi controlled hota hai", "Beginners ke liye naked selling se safer starting point hai"]}, {"heading": "Risk Management Rules", "points": ["Kabhi bhi naked options bina proper margin/risk-check ke mat becho", "Position sizing strict rakho — ek bade adverse move se bhi survive kar sako", "Hedge strategies (spreads) undefined risk se better hain", "Option selling ke liye proper capital aur experience dono zaroori hain"]}]},
    {"week": 37, "title": "Nifty Weekly Expiry Strategy", "title_en": "Nifty Weekly Expiry Strategy", "category": "Options", "level": "Intermediate", "description": "Thursday expiry — max pain, entry, exit", "slides": [{"heading": "Thursday Kyon Important Hai", "points": ["Nifty weekly options ki expiry Thursday ko hoti hai (holiday hone par pehle)", "Expiry day par volatility aur volume dono zyada hote hain", "Time decay expiry din sabse fast hoti hai", "New traders ke liye expiry day trading extra risky hoti hai"]}, {"heading": "Max Pain", "points": ["Max Pain woh strike price hai jahan maximum options worthless expire hongi", "Market kabhi kabhi expiry ke paas max pain ki taraf move karta hai", "Yeh guaranteed prediction tool nahi hai, sirf ek reference point hai", "Open interest data se max pain calculate kiya ja sakta hai"]}, {"heading": "Expiry Day Entry", "points": ["Expiry day par premiums bahut fast move karte hain (high gamma)", "Chhoti si price move se bhi bada percentage change ho sakta hai", "Experienced traders hi expiry day options trade karne ki salah dete hain", "Beginners ke liye expiry day avoid karna safer strategy hai"]}, {"heading": "Same Day Exit", "points": ["Expiry day options ko din khatam hone se pehle exit kar dena chahiye", "Overnight hold karne ka koi matlab nahi (agle din woh worthless ho jaayega agar OTM hai)", "Auto square-off se bachne ke liye khud hi time se exit karo", "Broker ke auto square-off rules bhi check karke rakho"]}, {"heading": "Last 30 Minutes Rule", "points": ["Expiry ke last 30 minutes mein volatility extreme ho sakti hai", "Naya position lena is window mein high risk maana jaata hai", "Existing positions ko is time monitor karte rehna zaroori hai", "Liquidity bhi kabhi kabhi is window mein patchy ho sakti hai"]}]},
    {"week": 38, "title": "India VIX — Fear Ka Indicator", "title_en": "India VIX — The Fear Indicator", "category": "Options", "level": "Intermediate", "description": "India VIX for options decisions", "slides": [{"heading": "VIX Kya Measure Karta Hai", "points": ["India VIX market ki expected volatility (agle 30 din) measure karta hai", "Isse 'Fear Index' bhi kehte hain", "High VIX = market mein uncertainty/fear zyada", "Low VIX = market calm aur stable expect kar raha hai"]}, {"heading": "VIX High — Options Mehnge", "points": ["High VIX ke time option premiums inflate ho jaate hain (high vega)", "Buyers ko zyada pay karna padta hai same strike ke liye", "Yeh time option sellers ke liye favorable ho sakta hai", "Events (budget, elections, results) ke around VIX spike karta hai"]}, {"heading": "VIX Low — Options Saste", "points": ["Low VIX ke time premiums relatively saste hote hain", "Option buyers ke liye yeh better entry environment ho sakta hai", "Lekin low VIX zyada der tak rehna bhi complacency dikha sakta hai", "Sudden VIX spike se low-VIX-bought options bhi fayda de sakte hain"]}, {"heading": "VIX 15-18 Best Zone", "points": ["Yeh zone generally balanced maana jaata hai — na zyada fear na zyada complacency", "Is range mein premiums reasonable hote hain risk ke against", "Extreme VIX (bahut high ya bahut low) extra caution maangta hai", "Yeh ek general guideline hai, absolute rule nahi"]}, {"heading": "AI360 VIX Filter", "points": ["System VIX ko option-related decisions mein context ke roop mein use karta hai", "Extreme VIX conditions mein extra caution recommend ki jaati hai", "Yeh purely informational filter hai, hard block nahi", "Owner apna final decision khud leta hai is data ke saath"]}]},
    {"week": 39, "title": "F&O Ban List — Kya Hota Hai", "title_en": "F&O Ban List — What It Is and Why", "category": "Options", "level": "Intermediate", "description": "SEBI F&O ban, open interest limits", "slides": [{"heading": "F&O Ban Kya Hota Hai", "points": ["Jab kisi stock ka open interest market-wide limit cross kar jaata hai", "NSE us stock mein NAYI F&O positions lena temporarily ban kar deta hai", "Existing positions square-off ki ja sakti hain, naye trades nahi", "Yeh ek risk-control mechanism hai excessive speculation rokne ke liye"]}, {"heading": "Open Interest Limit", "points": ["Open Interest total outstanding contracts (calls+puts+futures) hota hai", "SEBI/NSE har stock ke liye market-wide position limits define karte hain", "Limit cross hote hi ban list mein add ho jaata hai", "OI data NSE website par daily free available hota hai"]}, {"heading": "Ban Mein Kya Kar Sakte Hain", "points": ["Existing positions ko close/reduce kar sakte ho", "Naya position (fresh buy/sell) allowed nahi hota", "Cash market mein stock trading (shares buy/sell) affected nahi hoti", "Ban list daily update hoti hai NSE website par"]}, {"heading": "Warning Signs", "points": ["Stock jab ban ke close aata hai, extra volatility dikh sakti hai", "High speculation wale stocks ban list mein baar baar aa sakte hain", "Yeh kabhi kabhi excessive retail speculation ka signal hota hai", "F&O ban list ko regularly check karna informed trading ke liye zaroori hai"]}, {"heading": "NSE Website Free Check", "points": ["NSE ki official website par daily F&O ban list free milti hai", "Koi bhi trader is list ko check kar sakta hai bina paid subscription ke", "Trading shuru karne se pehle stock ka status verify karna chahiye", "Yeh basic due diligence har F&O trader ko karni chahiye"]}]},
    {"week": 40, "title": "Futures Trading — Basics Aur Risk", "title_en": "Futures Trading — Basics and Risks", "category": "Options", "level": "Advanced", "description": "Futures contracts — leverage, margin", "slides": [{"heading": "Futures Contract Kya Hota Hai", "points": ["Futures ek obligation hai (option se different) — buy/sell karna hi hoga expiry par", "Fixed price par future date mein asset buy/sell karne ka contract", "Options ke unlike, futures buyer aur seller dono obligated hote hain", "Futures mein premium nahi, margin deposit karna padta hai"]}, {"heading": "Leverage", "points": ["Futures mein poora contract value pay nahi karna padta, sirf margin", "Yeh leverage profits ko amplify karta hai, losses ko bhi", "Chhota adverse move bhi bada percentage loss bana sakta hai", "Leverage ek double-edged sword hai — samajhkar hi use karo"]}, {"heading": "Margin Call", "points": ["Agar position against move kare, additional margin maangi jaati hai", "Margin call ignore karne par broker forcibly position square-off kar sakta hai", "Margin requirements volatility ke hisaab se change hote rehte hain", "Sufficient buffer margin rakhna margin call se bachne ka tareeka hai"]}, {"heading": "Rollover", "points": ["Expiry se pehle current month position ko next month mein shift karna", "Rollover cost/benefit (spread) dhyaan se dekhna zaroori hai", "High rollover % market ka bullish/bearish sentiment bhi dikhata hai", "Beginners ko rollover mechanics samajhna zaroori hai future trading ke liye"]}, {"heading": "Futures vs Options", "points": ["Futures mein obligation hai, options mein sirf right (buyer ke liye)", "Futures ka risk unlimited dono direction mein ho sakta hai", "Options buyer ka risk sirf premium tak limited hota hai", "Beginners ke liye options generally futures se safer starting point hain"]}]},
    {"week": 41, "title": "Position Sizing — Ek Trade Mein Kitna Lagayein", "title_en": "Position Sizing — How Much to Risk Per Trade", "category": "Risk Management", "level": "Intermediate", "description": "Position sizing formula, 1% rule", "slides": [{"heading": "Position Sizing Kyon Important Hai", "points": ["Best strategy bhi galat position sizing se account blow-up kar sakti hai", "Position sizing decide karta hai ek single trade ka overall impact", "Yeh risk management ka sabse foundational element hai", "Professional traders strategy se zyada position sizing par focus karte hain"]}, {"heading": "1% Rule", "points": ["Total capital ka sirf 1% (kabhi kabhi 2%) ek trade mein risk karo", "Isse ek loss se account par minimal impact padta hai", "10 consecutive losses ke baad bhi capital ka bada hissa bacha rehta hai", "Yeh rule beginners aur professionals dono ke liye standard hai"]}, {"heading": "Kelly Criterion", "points": ["Ek mathematical formula jo optimal position size calculate karta hai", "Win rate aur risk-reward ratio dono factor karta hai", "Full Kelly aggressive hoti hai, traders often 'half Kelly' use karte hain", "Complex formula hai, practical use ke liye simplify kiya jaata hai"]}, {"heading": "Capital Tiers", "points": ["Chhota capital ke saath conservative position sizing zyada important hai", "Capital badhne ke saath diversification aur position count badh sakta hai", "Har tier ka apna risk tolerance aur strategy hona chahiye", "Capital grow karne ke saath rules bhi evolve karne chahiye"]}, {"heading": "AI360 Position Sizing", "points": ["System ka apna risk-based position sizing calculation hota hai", "Stop loss distance ke hisaab se quantity automatically adjust hoti hai", "Isse har trade ka dollar-risk consistent rehta hai", "Manual override se bhi rules ko bypass nahi kiya jaana chahiye"]}]},
    {"week": 42, "title": "Risk Management — Capital Bachana Pehle", "title_en": "Risk Management — Protecting Capital First", "category": "Risk Management", "level": "Intermediate", "description": "Complete risk management framework", "slides": [{"heading": "Capital Preservation Rule One", "points": ["Warren Buffett ka famous rule: 'Never lose money, Rule 2: never forget Rule 1'", "Paisa kamaane se pehle paisa bachana zyada important hai", "Bade losses se recover karna mathematically bahut mushkil hota hai", "Ek 50% loss ko recover karne ke liye 100% gain chahiye hota hai"]}, {"heading": "Maximum Drawdown", "points": ["Peak se lowest point tak ka % decline maximum drawdown kehlaata hai", "Yeh strategy ka worst-case historical performance dikhata hai", "Bada drawdown psychologically bhi bahut difficult hota hai handle karna", "Drawdown control karna consistent long-term returns ki key hai"]}, {"heading": "Concentration Risk", "points": ["Sara paisa ek hi stock/sector mein lagana concentration risk create karta hai", "Ek negative event poore portfolio ko heavily impact kar sakta hai", "Diversification (bina over-diversify kiye) yeh risk kam karta hai", "Concentration high-conviction ideas mein bhi limit ke andar honi chahiye"]}, {"heading": "Sector Concentration", "points": ["Alag stocks lekin same sector mein hona bhi ek chhupa hua risk hai", "Sector-wide negative news poore basket ko affect kar sakti hai", "Portfolio review mein sector-wise exposure bhi check karna chahiye", "20-25% se zyada ek sector mein exposure caution ka sign ho sakta hai"]}, {"heading": "When to Reduce Position", "points": ["Original investment thesis weaken ho jaaye toh position reduce karo", "Position size portfolio ke against bahut bada ho jaaye (concentration)", "Better opportunity mile toh capital rotate karna bhi valid hai", "Emotional attachment ki wajah se position hold karna avoid karo"]}]},
    {"week": 43, "title": "Trading Psychology — Mann Ko Control Karein", "title_en": "Trading Psychology — Controlling Your Mind", "category": "Psychology", "level": "Intermediate", "description": "FOMO, revenge trading, overconfidence", "slides": [{"heading": "90% Traders Kyon Harte Hain", "points": ["Zyada tar traders bad strategy ki wajah se nahi, indiscipline ki wajah se harte hain", "FOMO, revenge trading, aur overconfidence common causes hain", "System + discipline intelligence se zyada important hote hain trading mein", "Psychology ko ignore karna technical skills se bhi bada mistake hai"]}, {"heading": "FOMO", "points": ["FOMO (Fear Of Missing Out) traders ko bina proper setup ke entry karwata hai", "Ek bada move dekh kar chase karna aksar top par entry karwa deta hai", "FOMO se bachne ka tareeka hai apna trading plan strictly follow karna", "Missed opportunity accept karna FOMO trade se better hai"]}, {"heading": "Revenge Trading", "points": ["Loss ke baad turant usse recover karne ke liye bada trade lena", "Yeh emotional decision hota hai, logical nahi", "Revenge trading aksar original loss se bhi bada loss deta hai", "Loss ke baad break lena aur calm hokar analyze karna better strategy hai"]}, {"heading": "Overconfidence", "points": ["Kuch consecutive wins ke baad traders overconfident ho jaate hain", "Isse position sizing aur risk management rules break hone lagte hain", "Overconfidence bade, avoidable losses ka common reason hai", "Har trade ko independently treat karna, past streak ko ignore karke"]}, {"heading": "Trading Journal", "points": ["Har trade ka entry, exit, reasoning, aur outcome likhna", "Journal se patterns pata chalte hain — kya kaam kar raha hai, kya nahi", "Emotional state bhi note karna helpful hota hai (calm vs anxious)", "Regular journal review continuous improvement ka best tareeka hai"]}]},
    {"week": 44, "title": "Personal Finance — Savings Investment Insurance", "title_en": "Personal Finance — Savings Investment Insurance", "category": "Personal Finance", "level": "Beginner", "description": "Emergency fund, term insurance, health insurance", "slides": [{"heading": "Invest Karne Se Pehle Yeh Karo", "points": ["Emergency fund pehle banao, phir investing shuru karo", "High-interest debt (credit card) clear karo investing se pehle", "Term insurance aur health insurance basic protection ke liye zaroori hain", "In foundations ke bina investing risky ho sakti hai"]}, {"heading": "Emergency Fund", "points": ["6 mahine ke expenses jitna liquid fund rakhna chahiye", "Job loss ya medical emergency mein yeh cushion deta hai", "Liquid funds ya savings account mein rakhna better hai, stocks mein nahi", "Emergency fund complete hone tak aggressive investing avoid karo"]}, {"heading": "Term Insurance", "points": ["Pure life cover, bahut affordable premium mein bada cover deta hai", "Rs.1 crore cover sirf Rs.10,000-15,000/year mein mil sakta hai", "Family ki financial security ke liye sabse essential product hai", "Endowment/ULIP plans se term insurance kaafi behtar value deta hai"]}, {"heading": "Health Insurance", "points": ["Medical emergencies se savings ko protect karta hai", "Company ka group insurance kaafi nahi hota, personal cover bhi lo", "Family floater plan poore family ko cover karta hai", "Rs.5-10 lakh minimum cover recommend kiya jaata hai aajkal"]}, {"heading": "Invest Karne Ki Sahi Order", "points": ["Emergency fund → Term Insurance → Health Insurance → phir Investing", "Yeh order risk ko sahi tarike se manage karta hai", "Investing se pehle protection zaroori hai, warna ek emergency sab kuch kha sakti hai", "Yeh foundation strong hone ke baad hi equity/mutual funds mein aggressive ho sakte ho"]}]},
